WITH filtered AS (SELECT id, store_id, product_id, sale_date, units, revenue, ADD_MONTHS(sale_date, 6) AS sale_date_plus_months FROM store_sales WHERE product_id IN (1, 3, 4, 10)) SELECT CASE WHEN units >= 37 THEN 'LARGE' ELSE 'SMALL' END AS units_tier, product_id, APPROX_PERCENTILE(revenue, ARRAY(0.25, 0.5, 0.75)) AS revenue_quartiles, ROUND(AVG(units), 2) AS avg_units FROM filtered GROUP BY 1, 2;
